const updateSource = `-- name: UpdateSource :one
UPDATE discovery_sources SET name = $1, source_type = $2, url = $3, coverage = $4,
    poll_interval_seconds = $5, enabled = $6, crawl_policy = $7, updated_at = now()
WHERE slug = $8
RETURNING id, slug, name, source_type, url, coverage, poll_interval_seconds, enabled, crawl_policy, last_success_at, last_attempt_at, consecutive_failures, error_state, created_at, updated_at
`

type UpdateSourceParams struct {
	Name                string  `json:"name"`
	SourceType          string  `json:"source_type"`
	Url                 *string `json:"url"`
	Coverage            []byte  `json:"coverage"`
	PollIntervalSeconds int32   `json:"poll_interval_seconds"`
	Enabled             bool    `json:"enabled"`
	CrawlPolicy         []byte  `json:"crawl_policy"`
	Slug                string  `json:"slug"`
}

// The slug is the identity (it names the Temporal Schedule), so it is not updatable.
func (q *Queries) UpdateSource(ctx context.Context, arg UpdateSourceParams) (DiscoverySource, error) {
	row := q.db.QueryRow(ctx, updateSource,
		arg.Name,
		arg.SourceType,
		arg.Url,
		arg.Coverage,
		arg.PollIntervalSeconds,
		arg.Enabled,
		arg.CrawlPolicy,
		arg.Slug,
	)
	var i DiscoverySource
	err := row.Scan(
		&i.ID,
		&i.Slug,
		&i.Name,
		&i.SourceType,
		&i.Url,
		&i.Coverage,
		&i.PollIntervalSeconds,
		&i.Enabled,
		&i.CrawlPolicy,
		&i.LastSuccessAt,
		&i.LastAttemptAt,
		&i.ConsecutiveFailures,
		&i.ErrorState,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertDiscoveredURL = `-- name: UpsertDiscoveredURL :one
INSERT INTO discovered_urls (normalized_url, domain) VALUES ($1,$2)
ON CONFLICT (normalized_url) DO UPDATE SET normalized_url = EXCLUDED.normalized_url
RETURNING id, (xmax = 0) AS inserted
`

type UpsertDiscoveredURLParams struct {
	NormalizedUrl string `json:"normalized_url"`
	Domain        string `json:"domain"`
}

type UpsertDiscoveredURLRow struct {
	ID       uuid.UUID `json:"id"`
	Inserted bool      `json:"inserted"`
}

func (q *Queries) UpsertDiscoveredURL(ctx context.Context, arg UpsertDiscoveredURLParams) (UpsertDiscoveredURLRow, error) {
	row := q.db.QueryRow(ctx, upsertDiscoveredURL, arg.NormalizedUrl, arg.Domain)
	var i UpsertDiscoveredURLRow
	err := row.Scan(&i.ID, &i.Inserted)
	return i, err
}

const upsertQuery = `-- name: UpsertQuery :one
INSERT INTO discovery_queries (family, name, query_text, providers, region, enabled)
VALUES ($1,$2,$3,$4,$5,$6)
ON CONFLICT (name) DO UPDATE SET family = EXCLUDED.family, query_text = EXCLUDED.query_text, providers = EXCLUDED.providers,
    region = EXCLUDED.region, enabled = EXCLUDED.enabled
RETURNING id, family, name, query_text, providers, region, enabled, created_at
`

type UpsertQueryParams struct {
	Family    string   `json:"family"`
	Name      string   `json:"name"`
	QueryText string   `json:"query_text"`
	Providers []string `json:"providers"`
	Region    *string  `json:"region"`
	Enabled   bool     `json:"enabled"`
}

func (q *Queries) UpsertQuery(ctx context.Context, arg UpsertQueryParams) (DiscoveryQuery, error) {
	row := q.db.QueryRow(ctx, upsertQuery,
		arg.Family,
		arg.Name,
		arg.QueryText,
		arg.Providers,
		arg.Region,
		arg.Enabled,
	)
	var i DiscoveryQuery
	err := row.Scan(
		&i.ID,
		&i.Family,
		&i.Name,
		&i.QueryText,
		&i.Providers,
		&i.Region,
		&i.Enabled,
		&i.CreatedAt,
	)
	return i, err
}

